// ------------------------------------------------------------------- Speed

test('speed — mock pipeline (STFT + Wiener + iSTFT), 60 s stereo < 4 s', async () => {
	let fs = 44100, N = Math.round(fs * 60)
	let x = sine([90, 300], 0.3, fs, N)
	let model = { bass: 'b', vocal: 'v' }
	let sessionFactory = async spec => spec === 'b' ? bandMaskSession(0, 250, 4096, fs) : bandMaskSession(250, fs / 2, 4096, fs)

	let t0 = performance.now()
	await separate([x, x], { sampleRate: fs, modelType: 'mask', model, session: sessionFactory, wiener: 1, chunk: 30, overlap: 2 })
	let elapsed = (performance.now() - t0) / 1000
	console.log(`  (60 s stereo, 2 targets, wiener:1: ${elapsed.toFixed(2)} s)`)
	ok(elapsed < 4, `elapsed ${elapsed.toFixed(2)} s`)
})

// --------------------------------------------------------------- input errors

test('separate — rejects on missing sampleRate / model', async () => {
	await rejects(() => separate([new Float32Array(4)], {}), /sampleRate/, 'missing sampleRate')
	await rejects(() => separate([new Float32Array(4)], { sampleRate: 44100 }), /model/, 'missing model')
})
